entries[4134] = { ["name"] = "Nimboyas mystischer Stab", ["text"] = "Wird beim Aufheben gebunden\nZweihändig Stab\n74 - 112 Schaden Tempo 2.30\n(40.43 Schaden pro Sekunde)\n+8 Intelligenz\n+15 Willenskraft\nHaltbarkeit 100 / 100\nAnlegen: Erhöht die Zaubermacht um 16." }
