entries[4141] = { ["name"] = "Foliant des Essenherbeizauberns", ["text"] = "Klassen: Magier\nBenötigt Stufe 6\nBenutzen: Lehrt 'Essen herbeizaubern' (Rang 1).\nZaubert 20 Muffins herbei und versorgt den Magier sowie seine Verbündeten mit etwas Essbarem.\n\nHerbeigezauberte Gegenstände verschwinden, wenn Ihr Euch länger als 15 Minuten ausloggt.\nHerbeigezauberter Muffin\nHerbeigezauberter Gegenstand\nBenutzen: Stellt im Verlauf von 18 sec insgesamt 61.2 Gesundheit wieder her. Ihr müsst beim Essen sitzen bleiben." }
entries[4143] = { ["name"] = "Foliant des Essenherbeizauberns II", ["text"] = "Klassen: Magier\nBenötigt Stufe 12\nBenutzen: Lehrt 'Essen herbeizaubern' (Rang 2).\nZaubert 20 Laibe Brot herbei und versorgt den Magier sowie seine Verbündeten mit etwas Essbarem.\n\nHerbeigezauberte Gegenstände verschwinden, wenn Ihr Euch länger als 15 Minuten ausloggt.\nHerbeigezaubertes Brot\nHerbeigezauberter Gegenstand\nBenötigt Stufe 5\nBenutzen: Stellt im Verlauf von 21 sec insgesamt 243.6 Gesundheit wieder her. Ihr müsst beim Essen sitzen bleiben." }
entries[4145] = { ["name"] = "Foliant des Manaedelsteinherbeizauberns", ["text"] = "Klassen: Magier\nBenötigt Stufe 28\nBenutzen: Lehrt 'Manaedelstein herbeizaubern'.\nZaubert einen Manaachat herbei, der zum sofortigen Wiederherstellen von 390 to 410 Mana verwendet werden kann.\nManaachat\nWird beim Aufheben gebunden\nEinzigartig: [Mana Gem] (1)\nBenötigt Stufe 28\nBenutzen: Stellt 390 to 410 Mana wieder her. (2 Min Abklingzeit)" }
entries[4146] = { ["name"] = "Foliant der Verwandlung: Schaf", ["text"] = "Klassen: Magier\nBenötigt Stufe 40\nBenutzen: Lehrt 'Verwandlung: Schaf'.\nVerwandelt den Feind bis zu 10 sec lang in ein hilfloses Schaf, das weder Zauber wirken noch angreifen kann und sich um 60% langsamer bewegt." }
entries[4147] = { ["name"] = "Foliant des Essenherbeizauberns III", ["text"] = "Klassen: Magier\nBenötigt Stufe 22\nBenutzen: Lehrt 'Essen herbeizaubern' (Rang 3).\nZaubert 20 Laibe Roggenbrot herbei und versorgt den Magier sowie seine Verbündeten mit etwas Essbarem.\n\nHerbeigezauberte Gegenstände verschwinden, wenn Ihr Euch länger als 15 Minuten ausloggt.\nHerbeigezaubertes Roggenbrot\nHerbeigezauberter Gegenstand\nBenötigt Stufe 15\nBenutzen: Stellt im Verlauf von 24 sec insgesamt 552 Gesundheit wieder her. Ihr müsst beim Essen sitzen bleiben." }
entries[4148] = { ["name"] = "Foliant des Gegenzaubers", ["text"] = "Klassen: Magier\nBenötigt Stufe 24\nBenutzen: Lehrt 'Gegenzauber'.\nKontert das Zauberwirken des Feindes und verhindert 8 sec lang, dass ein Zauber dieser Art der Magie gewirkt werden kann. Führt zu einem hohen Maß an Bedrohung." }
entries[4149] = { ["name"] = "Foliant des Frostschilds III", ["text"] = "Klassen: Magier\nBenötigt Stufe 34\nBenutzen: Lehrt 'Frostschild' (Rang 3)." }
entries[4150] = { ["name"] = "Foliant des Wasserherbeizauberns IV", ["text"] = "Klassen: Magier\nBenötigt Stufe 30\nBenutzen: Lehrt 'Wasser herbeizaubern' (Rang 4).\nZaubert 20 Flaschen Quellwasser herbei und versorgt den Magier sowie seine Verbündeten mit etwas Trinkbarem.\n\nHerbeigezauberte Gegenstände verschwinden, wenn Ihr Euch länger als 15 Minuten ausloggt.\nHerbeigezaubertes Quellwasser\nHerbeigezauberter Gegenstand\nBenötigt Stufe 25\nBenutzen: Stellt im Verlauf von 27 sec insgesamt 1345 Mana wieder her. Ihr müsst beim Trinken sitzen bleiben." }
entries[4151] = { ["name"] = "Foliant des Frostblitzes IV", ["text"] = "Klassen: Magier\nBenötigt Stufe 20\nBenutzen: Lehrt 'Frostblitz' (Rang 4).\nSchleudert einen Frostblitz auf den Feind, der [Quellwert] bis [Quellwert] Frostschaden verursacht und sein Bewegungstempo 7 sec lang um 40% verringert.", ["unresolvedValues"] = true }
entries[4152] = { ["name"] = "Foliant des Essenherbeizauberns IV", ["text"] = "Klassen: Magier\nBenötigt Stufe 32\nBenutzen: Lehrt 'Essen herbeizaubern' (Rang 4).\nZaubert 20 Laibe Pumpernickel herbei und versorgt den Magier sowie seine Verbündeten mit etwas Essbarem.\n\nHerbeigezauberte Gegenstände verschwinden, wenn Ihr Euch länger als 15 Minuten ausloggt.\nHerbeigezauberter Pumpernickel\nHerbeigezauberter Gegenstand\nBenötigt Stufe 25\nBenutzen: Stellt im Verlauf von 27 sec insgesamt 874.8 Gesundheit wieder her. Ihr müsst beim Essen sitzen bleiben." }
entries[4153] = { ["name"] = "Foliant der arkanen Geschosse III", ["text"] = "Klassen: Magier\nBenötigt Stufe 24\nBenutzen: Lehrt 'Arkane Geschosse' (Rang 3).\nSchleudert arkane Geschosse auf den Feind und verursacht 5 sec lang alle 1 Sek. 58 Arkanschaden." }
entries[4154] = { ["name"] = "Foliant der Verlangsamung II", ["text"] = "Klassen: Magier\nBenötigt Stufe 40\nBenutzen: Lehrt 'Langsamkeit' (Rang 2).\nVerlangsamt 15 sec lang die Bewegung des Feindes um 60% und sein Angriffstempo um 54%." }
entries[4155] = { ["name"] = "Foliant der Wasserelementare II", ["text"] = "Klassen: Magier\nBenötigt Stufe 40\nBenutzen: Lehrt 'Wasserelementar' (Rang 2)." }
entries[4157] = { ["name"] = "Foliant des Magiedämpfens", ["text"] = "Klassen: Magier\nBenötigt Stufe 12\nBenutzen: Lehrt 'Magie dämpfen' (Rang 1).\nSchwächt gegen das anvisierte Gruppenmitglied gerichtete Magie ab, wobei der von Zaubern zugefügte Schaden um bis zu 10 und Heilzauber um bis zu 11 verringert werden. Hält 10 min lang an." }
entries[4158] = { ["name"] = "Foliant von Khadgars Öffnung III", ["text"] = "Klassen: Magier\nBenötigt Stufe 42\nBenutzen: Lehrt 'Aufstachelndes Totem' (Rang 4).\nBeschwört für 15 sec ein Totem der Steinklaue mit [280 + floor(Stamina * 0.05)]\nGesundheit zu Füßen des Zaubernden, das Kreaturen im Umkreis von 8 Metern durch Spott dazu bringt, es anzugreifen. Es besteht eine Chance von 50%, dass Gegner, die das Totem angreifen, für 3 sec betäubt werden. Das Totem der Steinklaue beschützt außerdem all Eure Totems, wodurch sie 170 Schaden absorbieren." }
entries[4159] = { ["name"] = "Foliant der arkanen Geschosse", ["text"] = "Klassen: Magier\nBenötigt Stufe 8\nBenutzen: Lehrt 'Arkane Geschosse' (Rang 1).\nSchleudert arkane Geschosse auf den Feind und verursacht 3 sec lang alle 1 Sek. 26 Arkanschaden." }
entries[4161] = { ["name"] = "Foliant des Feuerballs IV", ["text"] = "Klassen: Magier\nBenötigt Stufe 18\nBenutzen: Lehrt 'Feuerball' (Rang 4).\nSchleudert eine glühende Kugel hinaus, die 89 to 122 Feuerschaden sowie 8 sec lang insgesamt 12 zusätzlichen Feuerschaden verursacht." }
entries[4162] = { ["name"] = "Foliant des Blinzelns II", ["text"] = "Klassen: Magier\nBenötigt Stufe 38\nBenutzen: Lehrt 'Blinzeln' (Rang 2).\nTeleportiert den Zaubernden 20 Meter nach vorn, es sei denn, etwas steht im Weg. Befreit den Zaubernden auch von jeglichen Fesseln." }
entries[4164] = { ["name"] = "Buchband: Heiliges Licht V", ["text"] = "Klassen: Paladin\nBenötigt Stufe 30\nBenutzen: Lehrt 'Heiliges Licht' (Rang 5).\nHeilt ein befreundetes Ziel um 643 to 724." }
entries[4165] = { ["name"] = "Buchband: Heiliges Licht VI", ["text"] = "Klassen: Paladin\nBenötigt Stufe 38\nBenutzen: Lehrt 'Heiliges Licht' (Rang 6).\nHeilt ein befreundetes Ziel um 913 to 1017." }
entries[4166] = { ["name"] = "Buchband: Siegel des Schutzes", ["text"] = "Klassen: Paladin\nBenötigt Stufe 8\nBenutzen: Lehrt 'Siegel des Schutzes' (Rang 1).\nEin anvisiertes Gruppen- oder Schlachtzugsmitglied ist 6 sec lang vor allen körperlichen Angriffen geschützt, allerdings kann es dabei weder angreifen noch körperliche Fähigkeiten einsetzen. Spieler können pro Paladin immer nur von einer Hand berührt werden. Einmal geschützt, kann das Ziel 2 min lang nicht erneut zum Ziel von 'Gottesschild', 'Göttlicher Schutz' oder 'Hand des Schutzes' werden. Haben Spieler innerhalb der letzten 30 sec 'Zornige Vergeltung' genutzt, können sie ebenfalls nicht zum Ziel von 'Hand des Schutzes' werden." }
entries[4167] = { ["name"] = "Buchband: Richturteil", ["text"] = "Klassen: Paladin\nBenötigt Stufe 40\nBenutzen: Lehrt 'Richturteil'.\nSchleudert Blitze heiliger Macht in alle Richtungen, die untoten und dämonischen Zielen im Umkreis von 10 Metern (399 + 0.07 * Spell power + 0.07 * Attack power) bis (471 + 0.07 * Spell power + 0.07 * Attack power) Heiligschaden zufügen und sie 3 sec lang betäuben." }
entries[4168] = { ["name"] = "Schrifttafel des Totems der Einschnürung", ["text"] = "Klassen: Schamane\nBenötigt Stufe 16\nBenutzen: Lehrt 'Totem der Erdbindung'.\nBeschwört für 45 sec ein Totem der Erdbindung mit 5 Gesundheit zu Füßen des Zaubernden, das das Bewegungstempo von Feinden im Umkreis von 10 Metern verlangsamt." }
entries[4169] = { ["name"] = "Schrifttafel des unerschütterlichen Willens II", ["text"] = "Klassen: Schamane\nBenötigt Stufe 24\nBenutzen: Lehrt 'Unerschütterlicher Wille' (Rang 2)." }
entries[4170] = { ["name"] = "Schrifttafel des astralen Rückrufs", ["text"] = "Klassen: Schamane\nBenötigt Stufe 30\nBenutzen: Lehrt 'Astraler Rückruf'.\nReißt den Zaubernden durch den wirbelnden Nether zurück nach <Hearthstone Location>. Sprecht mit einem Gastwirt an einem anderen Ort, um Euren Heimatort zu ändern." }
entries[4171] = { ["name"] = "Schrifttafel des aufstachelnden Totems III", ["text"] = "Klassen: Schamane\nBenötigt Stufe 28\nBenutzen: Lehrt 'Aufstachelndes Totem' (Rang 3).\nBeschwört für 15 sec ein Totem der Steinklaue mit [220 + floor(Stamina * 0.05)] Gesundheit zu Füßen des Zaubernden, das Kreaturen im Umkreis von 8 Metern durch Spott dazu bringt, es anzugreifen. Es besteht eine Chance von 50%, dass Gegner, die das Totem angreifen, für 3 sec betäubt werden. Das Totem der Steinklaue beschützt außerdem all Eure Totems, wodurch sie 108 Schaden absorbieren." }
entries[4172] = { ["name"] = "Schrifttafel des Donnerknalls II", ["text"] = "Klassen: Schamane\nBenötigt Stufe 36\nBenutzen: Lehrt 'Donnerknall' (Rang 2)." }
entries[4173] = { ["name"] = "Schrifttafel des Schocks IV", ["text"] = "Klassen: Schamane\nBenötigt Stufe 28\nBenutzen: Lehrt 'Schock' (Rang 4).\nSchleudert sofort einen Blitzschlag auf das Ziel und fügt 191 to 202 Schaden zu." }
entries[4174] = { ["name"] = "Schrifttafel des Schocks V", ["text"] = "Klassen: Schamane\nBenötigt Stufe 36\nBenutzen: Lehrt 'Schock' (Rang 5).\nSchleudert sofort einen Blitzschlag auf das Ziel und fügt 269 to 286 Schaden zu." }
entries[4175] = { ["name"] = "Schrifttafel des Blitzschlagschildes IV", ["text"] = "Klassen: Schamane\nBenötigt Stufe 32\nBenutzen: Lehrt 'Blitzschlagschild' (Rang 4).\nDer Zaubernde ist von 3 Kugelblitzen umgeben. Wenn der Zaubernde von einem Nahkampf-, Distanz- oder Zauberangriff getroffen wird, erleidet der Angreifende 80 Naturschaden. Dies kostet einen Kugelblitz. Es wird immer nur ein einzelner Kugelblitz alle paar Sekunden abgefeuert. Hält 10 min lang an. Es kann immer nur ein Elementarschild auf dem Schamanen aktiv sein. (3.5s Abklingzeit)" }
entries[4176] = { ["name"] = "Schrifttafel der unsterblichen Stärke II", ["text"] = "Klassen: Schamane\nBenötigt Stufe 36\nBenutzen: Lehrt 'Unsterbliche Stärke' (Rang 2)." }
entries[4177] = { ["name"] = "Schrifttafel des Naturwiderstands", ["text"] = "Klassen: Schamane\nBenötigt Stufe 32\nBenutzen: Lehrt 'Naturwiderstand'." }
entries[4178] = { ["name"] = "Schrifttafel des Blitzschlags V", ["text"] = "Klassen: Schamane\nBenötigt Stufe 34\nBenutzen: Lehrt 'Blitzschlag' (Rang 5).\nSchleudert einen Blitz auf das Ziel und fügt ihm 131 to 149 Naturschaden zu." }
entries[4179] = { ["name"] = "Schrifttafel der Wiederherstellung V", ["text"] = "Klassen: Schamane\nBenötigt Stufe 32\nBenutzen: Lehrt 'Große Welle der Heilung' (Rang 1).\nHeilt ein befreundetes Ziel um 389 to 454." }
entries[4180] = { ["name"] = "Schrifttafel der Astralgestalt II", ["text"] = "Klassen: Schamane\nBenötigt Stufe 34\nBenutzen: Lehrt 'Astralgestalt' (Rang 2)." }
entries[4181] = { ["name"] = "Schrifttafel des aufstachelnden Totems IV", ["text"] = "Klassen: Schamane\nBenötigt Stufe 38\nBenutzen: Lehrt 'Aufstachelndes Totem' (Rang 4).\nBeschwört für 15 sec ein Totem der Steinklaue mit [280 + floor(Stamina * 0.05)]\nGesundheit zu Füßen des Zaubernden, das Kreaturen im Umkreis von 8 Metern durch Spott dazu bringt, es anzugreifen. Es besteht eine Chance von 50%, dass Gegner, die das Totem angreifen, für 3 sec betäubt werden. Das Totem der Steinklaue beschützt außerdem all Eure Totems, wodurch sie 170 Schaden absorbieren." }
entries[4182] = { ["name"] = "Schrifttafel des unerschütterlichen Willens III", ["text"] = "Klassen: Schamane\nBenötigt Stufe 38\nBenutzen: Lehrt 'Unerschütterlicher Wille' (Rang 3)." }
entries[4183] = { ["name"] = "Schrifttafel des Totems der Heilung V", ["text"] = "Klassen: Schamane\nBenötigt Stufe 36\nBenutzen: Lehrt 'Totem der Heilung' (Rang 5)." }
entries[4184] = { ["name"] = "Schrifttafel des Schmelzschlages V", ["text"] = "Klassen: Schamane\nBenötigt Stufe 38\nBenutzen: Lehrt 'Schmelzschlag' (Rang 5)." }
entries[4185] = { ["name"] = "Schrifttafel des astralen Gruppenrückrufs", ["text"] = "Klassen: Schamane\nBenötigt Stufe 40\nBenutzen: Lehrt 'Astraler Gruppenrückruf'." }
entries[4186] = { ["name"] = "Schrifttafel des Feuerwiderstands", ["text"] = "Klassen: Schamane\nBenötigt Stufe 32\nBenutzen: Lehrt 'Feuerwiderstand'." }
