entries[4189] = { ["name"] = "Schrifttafel des Kettenblitzschlages", ["text"] = "Klassen: Schamane\nBenötigt Stufe 32\nBenutzen: Lehrt 'Kettenblitzschlag' (Rang 1).\nSchleudert einen Blitzschlag auf den Feind, der 200 to 227 Naturschaden verursacht und zu in der Nähe befindlichen Feinden weiterspringt. Jeder Sprung verringert den Schaden um 30%. Wirkt auf insgesamt 3 Ziele." }
entries[4190] = { ["name"] = "Gefiederte Rüstung", ["text"] = "Brust Leder\n84 Rüstung\nHaltbarkeit 80 / 80\nBenötigt Stufe 22" }
entries[4191] = { ["name"] = "Ungenutzte gefiederte Gamaschen", ["text"] = "Beine Leder\n74 Rüstung\nHaltbarkeit 60 / 60\nBenötigt Stufe 22" }
