entries[4198] = { ["name"] = "Zauberfoliant des Seelentrichters", ["text"] = "Klassen: Hexenmeister\nBenötigt Stufe 12\nBenutzen: Lehrt 'Lebenslinie' (Rang 1).\nGibt dem Begleiter des Zaubernden 10 sec lang in jeder Sekunde 12 Gesundheit, solange der Zaubernde seine Kräfte kanalisiert." }
entries[4199] = { ["name"] = "Zauberfoliant des Seelentrichters II", ["text"] = "Klassen: Hexenmeister\nBenötigt Stufe 20\nBenutzen: Lehrt 'Lebenslinie' (Rang 2).\nGibt dem Begleiter des Zaubernden 10 sec lang in jeder Sekunde 24 Gesundheit, solange der Zaubernde seine Kräfte kanalisiert." }
entries[4200] = { ["name"] = "Zauberfoliant des Feuerbrandes III", ["text"] = "Klassen: Hexenmeister\nBenötigt Stufe 22\nBenutzen: Lehrt 'Feuerbrand' (Rang 3).\nVerbrennt den Feind und fügt 53 Feuerschaden sowie 15 sec lang insgesamt 90 zusätzlichen Feuerschaden zu." }
entries[4201] = { ["name"] = "Zauberfoliant des Auges von Kilrogg", ["text"] = "Klassen: Hexenmeister\nBenötigt Stufe 28\nBenutzen: Lehrt 'Auge von Kilrogg'.\nBeschwört das Auge von Kilrogg und bindet Eure Sicht daran. Das Auge bewegt sich schnell, ist jedoch sehr zerbrechlich." }
entries[4202] = { ["name"] = "Zauberfoliant der Furcht II", ["text"] = "Klassen: Hexenmeister\nBenötigt Stufe 24\nBenutzen: Lehrt 'Furcht' (Rang 2).\nErfüllt den Feind mit Furcht, woraufhin er bis zu 15 sec lang voller Furcht flüchtet. Erlittener Schaden kann den Effekt unterbrechen. Es kann immer nur jeweils ein einzelnes Ziel mit Furcht erfüllt werden." }
entries[4203] = { ["name"] = "Zauberfoliant der Pestilenz II", ["text"] = "Klassen: Hexenmeister\nBenötigt Stufe 26\nBenutzen: Lehrt 'Verderbnis' (Rang 2).\nVerdirbt das Ziel und verursacht 15 sec lang insgesamt 90 Schattenschaden." }
entries[4204] = { ["name"] = "Zauberfoliant des Seelentrichters III", ["text"] = "Klassen: Hexenmeister\nBenötigt Stufe 28\nBenutzen: Lehrt 'Lebenslinie' (Rang 3).\nGibt dem Begleiter des Zaubernden 10 sec lang in jeder Sekunde 43 Gesundheit, solange der Zaubernde seine Kräfte kanalisiert." }
entries[4205] = { ["name"] = "Zauberfoliant des Feuerbrandes IV", ["text"] = "Klassen: Hexenmeister\nBenötigt Stufe 34\nBenutzen: Lehrt 'Feuerbrand' (Rang 4).\nVerbrennt den Feind und fügt 101 Feuerschaden sowie 15 sec lang insgesamt 165 zusätzlichen Feuerschaden zu." }
entries[4206] = { ["name"] = "Zauberfoliant des Fluchs von Sargeras II", ["text"] = "Klassen: Hexenmeister\nBenötigt Stufe 24\nBenutzen: Lehrt 'Fluch der Pein' (Rang 2).\nVerflucht das Ziel mit Pein und fügt 24 sec lang insgesamt 180 Schattenschaden zu. Zuerst wird der Schaden langsam zugefügt und nimmt dann zu, bis der Fluch seine Gesamtdauer erreicht hat. Es kann immer nur jeweils ein Fluch pro Hexenmeister auf einem beliebigen Ziel aktiv sein." }
entries[4207] = { ["name"] = "Zauberfoliant des Fluchs von Archimonde", ["text"] = "Klassen: Hexenmeister\nBenötigt Stufe 30\nBenutzen: Lehrt 'Archimondes Fluch'.\nVerflucht das Ziel mit drohender Verdammnis und verursacht nach Ablauf von 1 min 3200 Schattenschaden. Wenn das Ziel Erfahrung oder Ehre gewährt und durch diesen Schaden stirbt, wird eine Verdammniswache beschworen. Kann nicht auf Spieler gewirkt werden." }
entries[4208] = { ["name"] = "Zauberfoliant der Gedankenbombe", ["text"] = "Klassen: Hexenmeister\nBenötigt Stufe 32\nBenutzen: Lehrt 'Gedankenbombe'." }
entries[4209] = { ["name"] = "Zauberfoliant des Schattenzauberschutzes", ["text"] = "Klassen: Hexenmeister\nBenötigt Stufe 30\nBenutzen: Lehrt 'Schattenzauberschutz'.\nAbsorbiert 290 Schattenschaden. Hält 30 sec lang an." }
entries[4210] = { ["name"] = "Zauberfoliant der geringen Blutsteinherstellung", ["text"] = "Klassen: Hexenmeister\nBenötigt Stufe 14\nBenutzen: Lehrt 'Geringen Gesundheitsstein herstellen'.\nLässt einen geringen Gesundheitsstein entstehen, der verwendet werden kann, um 250 Gesundheit wiederherzustellen.\n\nHerbeigezauberte Gegenstände verschwinden, wenn Ihr Euch länger als 15 Minuten ausloggt." }
entries[4211] = { ["name"] = "Zauberfoliant der Pestilenz", ["text"] = "Klassen: Hexenmeister\nBenötigt Stufe 14\nBenutzen: Lehrt 'Verderbnis' (Rang 1).\nVerdirbt das Ziel und verursacht 12 sec lang insgesamt 40 Schattenschaden." }
entries[4212] = { ["name"] = "Zauberfoliant des Fluchs von Mannoroth III", ["text"] = "Klassen: Hexenmeister\nBenötigt Stufe 32\nBenutzen: Lehrt 'Fluch der Schwäche' (Rang 3).\nDie Nahkampfangriffskraft des Ziels wird um 64 verringert, seine Rüstung um 5%. Hält 2 min lang an. Es kann immer nur jeweils ein Fluch pro Hexenmeister auf einem beliebigen Ziel aktiv sein." }
entries[4213] = { ["name"] = "Zauberfoliant der Verdammnis", ["text"] = "Wird beim Aufheben gebunden\nKlassen: Hexenmeister\nBenötigt Stufe 60\nBenutzen: Lehrt das Ritual der Verdammnis.\nBeginnt ein Ritual, das die Gesundheit eines zufälligen Teilnehmers opfert, um eine Verdammniswache zu beschwören. Um das Ritual zu vervollständigen, werden der Zaubernde und 4 zusätzliche Gruppenmitglieder benötigt. Um teilzunehmen, müssen alle Spieler auf das Portal rechtsklicken und dürfen sich nicht bewegen, bis das Ritual abgeschlossen ist." }
entries[4214] = { ["name"] = "Zauberfoliant des Lebenssaugers III", ["text"] = "Klassen: Hexenmeister\nBenötigt Stufe 30\nBenutzen: Lehrt 'Blutsauger' (Rang 3).\nÜberträgt alle 1 Sek. 29 Gesundheit vom Ziel auf den Zaubernden. Hält 5 sec lang an." }
entries[4215] = { ["name"] = "Zauberfoliant des Feuerregens", ["text"] = "Klassen: Hexenmeister\nBenötigt Stufe 20\nBenutzen: Lehrt 'Feuerregen' (Rang 1).\nLässt einen feurigen Regen niedergehen, der 8 sec lang Feinde im Wirkungsbereich mit insgesamt ( 62 * 4) Feuerschaden verbrennt." }
entries[4216] = { ["name"] = "Zauberfoliant des heiligen Zauberschutzes", ["text"] = "Klassen: Hexenmeister\nBenötigt Stufe 40\nBenutzen: Lehrt 'Heiliger Zauberschutz'." }
entries[4217] = { ["name"] = "Zauberfoliant des Seelentrichters IV", ["text"] = "Klassen: Hexenmeister\nBenötigt Stufe 36\nBenutzen: Lehrt 'Lebenslinie' (Rang 4).\nGibt dem Begleiter des Zaubernden 10 sec lang in jeder Sekunde 64 Gesundheit, solange der Zaubernde seine Kräfte kanalisiert." }
entries[4218] = { ["name"] = "Zauberfoliant der Blutsteinherstellung", ["text"] = "Klassen: Hexenmeister\nBenötigt Stufe 26\nBenutzen: Lehrt 'Gesundheitsstein herstellen'.\nLässt einen Gesundheitsstein entstehen, der verwendet werden kann, um sofort 500 Gesundheit wiederherzustellen.\n\nHerbeigezauberte Gegenstände verschwinden, wenn Ihr Euch länger als 15 Minuten ausloggt." }
entries[4219] = { ["name"] = "Zauberfoliant des brennenden Geistes IV", ["text"] = "Klassen: Hexenmeister\nBenötigt Stufe 40\nBenutzen: Lehrt 'Brennender Geist' (Rang 4)." }
entries[4220] = { ["name"] = "Zauberfoliant des Siedebluts III", ["text"] = "Klassen: Hexenmeister\nBenötigt Stufe 30\nBenutzen: Lehrt 'Siedeblut' (Rang 3)." }
entries[4221] = { ["name"] = "Zauberfoliant der Entdeckung von Unsichtbarkeit", ["text"] = "Klassen: Hexenmeister\nBenötigt Stufe 40\nBenutzen: Lehrt 'Unsichtbarkeit entdecken'." }
entries[4223] = { ["name"] = "Buch des Magie Aufhebens", ["text"] = "Klassen: Druide\nBenötigt Stufe 36\nBenutzen: Lehrt 'Magie aufheben' (Rang 1)." }
entries[4225] = { ["name"] = "Buch der Wucherwurzeln III", ["text"] = "Klassen: Druide\nBenötigt Stufe 28\nBenutzen: Lehrt 'Wucherwurzeln' (Rang 3).\nLässt das Ziel an Ort und Stelle festwurzeln und verursacht im Verlauf von 18 sec insgesamt 90 Naturschaden. Erlittener Schaden kann den Effekt unterbrechen." }
entries[4226] = { ["name"] = "Buch des Zorns VI", ["text"] = "Klassen: Druide\nBenötigt Stufe 38\nBenutzen: Lehrt 'Zorn' (Rang 6).\nVerursacht 178 to 201 Naturschaden am Ziel." }
