entries[4265] = { ["name"] = "Schweres Rüstungsset", ["text"] = "Benötigt Stufe 20\nBenutzen: Den Rüstungswert eines Gegenstands, der auf der Brust, an den Beinen, Händen oder Füßen getragen wird, dauerhaft um 24 erhöhen. Kann nur auf Gegenstände der Stufe 15 oder höher angewendet werden." }
entries[4266] = { ["name"] = "Kodex des inneren Feuers II", ["text"] = "Klassen: Priester\nBenötigt Stufe 20\nBenutzen: Lehrt 'Inneres Feuer' (Rang 2).\nDer Zaubernde wird von einem Schub heiliger Energie erfüllt, der seine Rüstung um 720 erhöht. Ein erlittener Nahkampf- oder Distanzangriffstreffer verbraucht eine Aufladung. Hält 30 min lang an oder bis alle 20 Aufladungen verbraucht sind." }
