entries[4280] = { ["name"] = "Kodex des Heiligen Wortes: Schild IV", ["text"] = "Klassen: Priester\nBenötigt Stufe 24\nBenutzen: Lehrt 'Heiliges Wort: Schild' (Rang 4).\nNutzt die Seelenkraft eines befreundeten Ziels, um es mit einem Schild zu umhüllen und so 244 Schaden zu absorbieren. Hält 30 sec lang an. Solange der Schild hält, wird das Zauberwirken durch erlittenen Schaden nicht unterbrochen. Nachdem das Ziel einmal abgeschirmt wurde, kann es 15 sec lang nicht wieder abgeschirmt werden." }
entries[4281] = { ["name"] = "Kodex des Schattenschutzes", ["text"] = "Klassen: Priester\nBenötigt Stufe 30\nBenutzen: Lehrt 'Schattenschutz'.\nErhöht 10 min lang die Widerstandskraft des Ziels gegen alle Schattenzauber um 30." }
entries[4282] = { ["name"] = "Kodex der Magiebannung II", ["text"] = "Klassen: Priester\nBenötigt Stufe 36\nBenutzen: Lehrt 'Magiebannung' (Rang 2).\nBannt auf dem Ziel liegende Magie und entfernt 2 schädliche Zauber von einem Freund oder 2 nützliche Zauber von einem Feind." }
entries[4283] = { ["name"] = "Kodex des Schlafs III", ["text"] = "Klassen: Priester\nBenötigt Stufe 40\nBenutzen: Lehrt 'Schlaf' (Rang 3)." }
