entries[4293] = { ["name"] = "Muster: Lederweste des Hügelwächters", ["text"] = "Benötigt Lederverarbeitung (100)\nBenutzen: Lehrt Euch die Herstellung einer Lederweste des Hügelwächters.\nLederweste des Hügelwächters\nWird beim Anlegen gebunden\nBrust Leder\n78 Rüstung\n+4 Ausdauer\nHaltbarkeit 70 / 70\nBenötigt Stufe 15\nAnlegen: Erhöht die Zaubermacht um 5.\nBenötigt Feine Ledertunika , Geschmeidiger leichter Balg (2), Grober Faden (2)" }
entries[4294] = { ["name"] = "Muster: Gürtel des Hügelwächters", ["text"] = "Benötigt Lederverarbeitung (120)\nBenutzen: Lehrt Euch die Herstellung eines Gürtels des Hügelwächters.\nGürtel des Hügelwächters\nWird beim Anlegen gebunden\nTaille Leder\n48 Rüstung\n+4 Ausdauer\nHaltbarkeit 30 / 30\nBenötigt Stufe 20\nAnlegen: Erhöht die Zaubermacht um 5.\nBenötigt Mittleres Leder (8), Elixier der Weisheit , Feiner Faden (2)" }
entries[4296] = { ["name"] = "Muster: Dunkle Lederschultern", ["text"] = "Benötigt Lederverarbeitung (140)\nBenutzen: Lehrt Euch die Herstellung von dunklen Lederschultern.\nDunkle Lederschultern\nWird beim Anlegen gebunden\nSchulter Leder\n68 Rüstung\n+7 Beweglichkeit\nHaltbarkeit 50 / 50\nBenötigt Stufe 23\nBenötigt Mittleres Leder (12), Elixier der geringen Beweglichkeit , Grauer Farbstoff , Feiner Faden (2)" }
entries[4297] = { ["name"] = "Muster: Barbarische Handschuhe", ["text"] = "Benötigt Lederverarbeitung (150)\nBenutzen: Lehrt Euch die Herstellung von barbarischen Handschuhen.\nBarbarische Handschuhe\nWird beim Anlegen gebunden\nHände Leder\n58 Rüstung\n+6 Ausdauer\nHaltbarkeit 30 / 30\nBenötigt Stufe 25\nAnlegen: Erhöht die Angriffskraft um 10.\nBenötigt Schweres Leder (6), Großer Fangzahn (2), Feiner Faden" }
entries[4298] = { ["name"] = "Muster: Wächtergürtel", ["text"] = "Benötigt Lederverarbeitung (170)\nBenutzen: Lehrt Euch die Herstellung eines Wächtergürtels.\nWächtergürtel\nWird beim Anlegen gebunden\nTaille Leder\n56 Rüstung\n+7 Intelligenz\nHaltbarkeit 30 / 30\nBenötigt Stufe 29\nAnlegen: Erhöht die Zaubermacht um 7.\nBenötigt Geschmeidiger schwerer Balg (2), Schweres Leder (4), Feiner Faden , Eiserne Gürtelschnalle" }
entries[4299] = { ["name"] = "Muster: Wächterrüstung", ["text"] = "Benötigt Lederverarbeitung (175)\nBenutzen: Lehrt Euch die Herstellung einer Wächterrüstung.\nWächterrüstung\nWird beim Anlegen gebunden\nBrust Leder\n102 Rüstung\n+10 Intelligenz\nHaltbarkeit 85 / 85\nBenötigt Stufe 30\nAnlegen: Erhöht die Zaubermacht um 10.\nBenötigt Geschmeidiger schwerer Balg (2), Schweres Leder (12), Schattenöl , Feiner Faden (2)" }
entries[4300] = { ["name"] = "Muster: Wächterlederarmschienen", ["text"] = "Benötigt Lederverarbeitung (195)\nBenutzen: Lehrt Euch die Herstellung von Wächterlederarmschienen.\nWächterlederarmschienen\nWird beim Anlegen gebunden\nHandgelenke Leder\n48 Rüstung\n+6 Willenskraft\nHaltbarkeit 30 / 30\nBenötigt Stufe 34\nAnlegen: Erhöht die Zaubermacht um 7.\nBenötigt Schweres Leder (6), Geschmeidiger schwerer Balg (2), Seidenfaden" }
