entries[4407] = { ["name"] = "Genaues Zielfernrohr", ["text"] = "Benötigt Stufe 20\nBenutzen: Verbindet ein Zielfernrohr dauerhaft mit dem Bogen oder der Schusswaffe und erhöht den damit zugefügten Schaden um 3.\n\nDurch das Anbringen des Fernrohrs an die Fernkampfwaffe wird diese seelengebunden." }
entries[4408] = { ["name"] = "Bauplan: Kasten mit mechanischem Eichhörnchen", ["text"] = "Benötigt Ingenieurskunst (75)\nBenutzen: Lehrt Euch die Herstellung eines Kastens mit mechanischem Eichhörnchen.\nKasten mit mechanischem Eichhörnchen\nBenutzen: Lehrt Euch, wie man dieses Haustier beschwört.\nErschafft ein mechanisches Eichhörnchen, das Euch folgt. Mit Rechtsklick Euer Eichhörnchen beschwören und freigeben.\nBenötigt Kupfermodulator , Eine Hand voll Kupferbolzen , Kupferbarren , Malachit (2)" }
entries[4409] = { ["name"] = "Bauplan: Kleine Zephyriumladung", ["text"] = "Benötigt Ingenieurskunst (100)\nBenutzen: Lehrt Euch die Herstellung einer kleinen Zephyriumladung.\nEine kleine Zephyriumladung, die ausreicht, um einige Türen aufzusprengen.\nKleine Zephyriumladung\nBenötigt Ingenieurskunst (100)\nBenutzen: Sprengt einfache verschlossene Türen und Truhen auf.\nBenötigt Grobes Sprengpulver (2), Kupfermodulator , Leichtes Leder , Erfrischendes Quellwasser" }
entries[4410] = { ["name"] = "Bauplan: Schattenschutzbrille", ["text"] = "Benötigt Ingenieurskunst (120)\nBenutzen: Lehrt Euch die Herstellung einer Schattenschutzbrille.\nSchattenschutzbrille\nWird beim Anlegen gebunden\nKopf Stoff\n31 Rüstung\n+5 Intelligenz\n+6 Willenskraft\nHaltbarkeit 40 / 40\nBenötigt Ingenieurskunst (120)\nBenötigt Mittleres Leder (4), Schattenedelstein (2)" }
entries[4411] = { ["name"] = "Bauplan: Flammendeflektor", ["text"] = "Benötigt Ingenieurskunst (125)\nBenutzen: Lehrt Euch die Herstellung eines Flammendeflektors.\nFlammendeflektor\nBenötigt Stufe 15\nBenutzen: Absorbiert 500 Feuerschaden. Hält 1 min lang an. (15 Min Abklingzeit)\n5 AufladungenBenötigt Surrendes bronzenes Dingsda , Kleiner Flammenbeutel" }
entries[4412] = { ["name"] = "Bauplan: Mondsichtgewehr", ["text"] = "Benötigt Ingenieurskunst (145)\nBenutzen: Lehrt Euch die Herstellung eines Mondsichtgewehrs.\nMondsichtgewehr\nWird beim Anlegen gebunden\nDistanz Schusswaffe\n19 - 35 Schaden Tempo 1.70\n(15.88 Schaden pro Sekunde)\nHaltbarkeit 65 / 65\nBenötigt Stufe 24\nBenötigt Bronzeröhre (3), Surrendes bronzenes Dingsda (3), Schwerer Griff , Geringer Mondstein (2)" }
entries[4413] = { ["name"] = "Bauplan: Diskombobulatorstrahl", ["text"] = "Benötigt Ingenieurskunst (160)\nBenutzen: Lehrt Euch die Herstellung eines Diskombobulatorstrahls.\nDiskombobulatorstrahl\nBenutzen: Verwandelt das Ziel in einen Lepragnom und verringert 12 sec lang seinen Nahkampfschaden und seine Zaubermacht um 40 sowie sein Bewegungstempo um 20%. (1 Min Abklingzeit)\n5 AufladungenBenötigt Surrendes bronzenes Dingsda (3), Seidenstoff (2), Jade , Bronzeröhre" }
entries[4414] = { ["name"] = "Bauplan: Tragbarer bronzener Mörser", ["text"] = "Benötigt Ingenieurskunst (165)\nBenutzen: Lehrt Euch die Herstellung eines tragbaren bronzenen Mörsers.\nTragbarer bronzener Mörser\nBenötigt Ingenieurskunst (165)\nBenutzen: Fügt 85 to 115 Feuerschaden zu und betäubt Ziele 2 sec lang in einem Radius von 5 Metern. Jeglicher Schaden wird den Effekt abbrechen. Unzuverlässig gegen Ziele über Stufe 44. (1 Min Abklingzeit)\n8 AufladungenBenötigt Bronzeröhre (4), Eisenstrebe , Schweres Sprengpulver (4), Mittleres Leder (4)" }
entries[4415] = { ["name"] = "Bauplan: Handwerkermonokel", ["text"] = "Benötigt Ingenieurskunst (185)\nBenutzen: Lehrt Euch die Herstellung eines Handwerkermonokels.\nHandwerkermonokel\nWird beim Anlegen gebunden\nKopf Stoff\n40 Rüstung\n+15 Intelligenz\nHaltbarkeit 45 / 45\nBenötigt Ingenieurskunst (185)\nBenötigt Schweres Leder (6), Citrin (2)" }
entries[4416] = { ["name"] = "Bauplan: Goblinlandmine", ["text"] = "Benötigt Ingenieurskunst (195)\nBenutzen: Lehrt Euch die Herstellung einer Goblinlandmine.\nEine Goblinlandmine bauen.\nGoblinlandmine\nBenötigt Ingenieurskunst (195)\nBenutzen: Platziert die Goblinlandmine auf dem Boden. Sie explodiert, sobald eine feindliche Kreatur an ihr vorbeigeht, und fügt ihr 394 to 506 Feuerschaden zu. Die Mine ist 1 min lang aktiv. (1 Min Abklingzeit)\nBenötigt Schweres Sprengpulver (3), Eisenbarren (2), Gyrochronatom" }
entries[4417] = { ["name"] = "Bauplan: Große Zephyriumladung", ["text"] = "Benötigt Ingenieurskunst (200)\nBenutzen: Lehrt Euch die Herstellung einer großen Zephyriumladung.\nGroße Zephyriumladung\nBenötigt Ingenieurskunst (200)\nBenutzen: Sprengt schwere verschlossene Türen und Truhen auf.\nBenötigt Robustes Sprengpulver (2), Schweres Leder (2), Erfrischendes Quellwasser" }
